template<class charT, class traits = regex_traits<charT>>
class basic_regex;

template<class BidirectionalIt, class Alloc = allocator<typename iterator_traits<BidirectionalIt>::value_type>>
bool regex_match(BidirectionalIt first, BidirectionalIt last,
                 match_results<BidirectionalIt, Alloc>& m,
                 const basic_regex<charT, traits>& re,
                 regex_constants::match_flag_type flags = regex_constants::match_default);
// Implementation notes: The function iterates over the input range [first, last] using the regex engine. The compiler may optimize the call to basic_regex constructor for repeated uses, but matching is runtime-bound, involving dynamic memory allocation for match_results and potential stack growth for backtracking.

code_example:
#include <iostream>
#include <regex>
#include <string>

int main() {
    std::string input = "Hello, World!";
    std::regex pattern(R"(Hello,\sWorld!)");  // Escaped for literal match
    std::smatch match_results;  // Specialized match_results for strings
    bool result = std::regex_match(input, match_results, pattern);
    if (result) {
        std::cout << "Full match succeeded." << std::endl;
        for (size_t i = 0; i < match_results.size(); ++i) {
            std::cout << "Submatch " << i << ": " << match_results[i].str() << std::endl;
        }
    } else {
        std::cout << "No match." << std::endl;
    }
    return 0;
}
